            Exercise.MathChallenge(id = "mit_6_042j_2010_s009_e03", prompt = "Trois messages doivent traverser la même liaison qui transmet un message par unité de temps. Quelle borne minimale de temps impose cette liaison ?", options = listOf("3", "1", "2", "0"), correctOptionIndex = 0, explanation = "La liaison doit effectuer trois transmissions distinctes, donc au moins trois unités, même si les chemins sont courts.", hint = "Raisonne sur la capacité de la ressource partagée."),
