            Exercise.MultipleChoice(id = "mit_6_042j_2010_s011_e04", prompt = "Dans l’ordre de divisibilité sur {1,2,3,6}, quelle paire est incomparable ?", options = listOf("1 et 6", "2 et 3", "1 et 2", "2 et 6"), correctOptionIndex = 1, explanation = "Ni 2 ne divise 3, ni 3 ne divise 2. Chaque autre paire proposée possède une relation de divisibilité.", hint = "Teste les deux directions.")
        ),
        objective = "Reconnaître un ordre partiel et déduire des plannings compatibles.",
        learningNotes = "Une relation binaire est un ensemble de couples. Une équivalence est réflexive, symétrique et transitive. Elle partitionne le domaine en classes. Un ordre partiel large est réflexif, antisymétrique et transitif, sans obliger chaque paire à être comparable. Les dépendances strictes d'un planning forment plutôt un DAG. Leur clôture réflexive et transitive fournit l'ordre large correspondant. Pour A avant B et C, puis B et C avant D, B et C sont incomparables. Un tri topologique peut choisir l'un ou l'autre en premier. Si toutes les tâches durent une unité et que les ressources parallèles sont illimitées, le plus long chemin de dépendances impose trois créneaux : A, puis B et C, puis D. Les hypothèses sur durée et ressources sont essentielles.",
