            Exercise.MathChallenge(id = "mit_6_042j_2010_s012_e02", prompt = "Quelle est la somme des entiers de 1 à 20 inclus ?", options = listOf("190", "420", "210", "200"), correctOptionIndex = 2, explanation = "La formule n(n+1)/2 donne 20×21/2=210.", hint = "Associe premier et dernier termes."),
            Exercise.MathChallenge(id = "mit_6_042j_2010_s012_e03", prompt = "Pour |x|<1, quelle valeur a Σ de i=1 à l’infini de i/3^i ?", options = listOf("1/4", "3/4", "1/3", "3/2"), correctOptionIndex = 1, explanation = "Avec x=1/3, x/(1-x)²=(1/3)/(2/3)²=3/4.", hint = "Utilise la somme géométrique pondérée."),
            Exercise.MultipleChoice(id = "mit_6_042j_2010_s012_e04", prompt = "Pourquoi la formule (1-x^(n+1))/(1-x) doit-elle être traitée séparément en x=1 ?", options = listOf("Son dénominateur est nul, alors que la somme finie vaut n+1.", "La somme finie n’existe plus.", "Tous les termes deviennent nuls.", "La somme vaut toujours zéro."), correctOptionIndex = 0, explanation = "La somme finie conserve un sens, mais cette expression quotient ne peut pas être évaluée directement en x=1.", hint = "Distingue une formule de sa valeur sur un cas exclu.")
        ),
        objective = "Choisir une identité de somme et contrôler son domaine.",
        learningNotes = "Une somme peut être remplacée par une forme fermée ou encadrée lorsqu'une expression exacte serait peu utile. Pour la somme géométrique S=1+x+...+x^n, multiplier par x puis soustraire laisse (1-x)S=1-x^(n+1), donc S=(1-x^(n+1))/(1-x) si x≠1. Si x=1, il faut traiter séparément les n+1 termes égaux à un. Pour |x|<1, la limite donne 1/(1-x). Dériver cette identité permet de calculer des sommes pondérées telles que Σi x^i=x/(1-x)², dans ce même domaine de convergence. Les sommes arithmétiques et les comparaisons avec des intégrales complètent la méthode. Avant de manipuler une somme infinie, on vérifie sa convergence et les conditions de la transformation.",
