    private fun lesson013() = Lesson(
        id = "mit_6_042j_2010_s013",
        title = "Encadrer une croissance et lire une équivalence",
        xpReward = 20,
        isLocked = false,
        exercises = listOf(
            Exercise.MultipleChoice(id = "mit_6_042j_2010_s013_e01", prompt = "Quel est l’ordre serré de 5n³+2n²+9 quand n tend vers l’infini ?", options = listOf("Θ(log n)", "Θ(1)", "Θ(n³)", "Θ(n²)"), correctOptionIndex = 2, explanation = "Le terme cubique domine. Le rapport à n³ tend vers 5, une constante positive.", hint = "Divise tous les termes par la puissance dominante."),
            Exercise.MultipleChoice(id = "mit_6_042j_2010_s013_e02", prompt = "Quelle limite a (3n²+2n)/n² ?", options = listOf("5", "3", "0", "1"), correctOptionIndex = 1, explanation = "Le quotient vaut 3+2/n, qui tend vers 3. Cela donne Θ(n²), mais pas une équivalence avec n².", hint = "Simplifie le quotient avant de prendre sa limite."),
            Exercise.MathChallenge(id = "mit_6_042j_2010_s013_e03", prompt = "Quelle valeur exacte a H4=1+1/2+1/3+1/4 ?", options = listOf("25/12", "12/25", "2", "11/6"), correctOptionIndex = 0, explanation = "Sur le dénominateur 12, la somme vaut (12+6+4+3)/12=25/12.", hint = "Cherche un dénominateur commun."),
            Exercise.MultipleChoice(id = "mit_6_042j_2010_s013_e04", prompt = "Pourquoi n! n’est-il pas Θ(n^n) ?", options = listOf("Les deux expressions sont identiques.", "Le rapport tend vers un.", "Une factorielle est toujours plus grande que n^n.", "Le rapport n!/n^n tend vers zéro, notamment par Stirling."), correctOptionIndex = 3, explanation = "Stirling donne un rapport équivalent à √(2πn)e^-n, qui tend vers zéro. Aucun minorant constant positif ne subsiste.", hint = "Étudie le rapport au lieu de comparer seulement quelques valeurs.")
        ),
        objective = "Distinguer O, Θ et équivalence asymptotique.",
        learningNotes = "Pour une fonction positive décroissante, comparer rectangles et intégrale fournit des bornes de somme. Ainsi le nombre harmonique H_n=Σ1/i se situe entre ln(n+1) et 1+ln n. Il a donc un ordre logarithmique. Les notations expriment des degrés différents de précision : f=O(g) donne un majorant à constante près, f=Θ(g) fournit aussi un minorant, tandis que f~g demande que f/g tende vers un. Par exemple 3n²+2n est Θ(n²), mais n'est pas équivalent à n² car le rapport tend vers trois. Les produits, notamment n!, peuvent être étudiés en sommant leurs logarithmes. La formule de Stirling affine cette approche avec n!~√(2πn)(n/e)^n. Le facteur racine ne peut pas être supprimé si l'on prétend à une équivalence.",
        sourceUrls = listOf("https://ocw.mit.edu/courses/6-042j-mathematics-for-computer-science-fall-2010/resources/lecture-13-sums-and-asymptotics/", "https://ocw.mit.edu/courses/6-042j-mathematics-for-computer-science-fall-2010/0ee7810a0f2b2cded346b7ae55814e21_X9eErxRjQEI.pdf", "https://ocw.mit.edu/courses/6-042j-mathematics-for-computer-science-fall-2010/c110f2c1483fd57a9c97ebde0be38f75_MIT6_042JF10_chap09.pdf"),
        requiresPreviousLesson = true,
        sourceSessionNumber = 13,
        sourceTitle = "Lecture 13: Sums and Asymptotics",
