            Exercise.MathChallenge(id = "mit_6_042j_2010_s014_e01", prompt = "Combien de mouvements impose H(n)=2H(n-1)+1, H(0)=0, pour quatre disques ?", options = listOf("7", "15", "8", "16"), correctOptionIndex = 1, explanation = "Les valeurs sont 0,1,3,7,15 ; la forme fermée est 2^4-1=15.", hint = "Déroule quatre fois la relation."),
            Exercise.MathChallenge(id = "mit_6_042j_2010_s014_e02", prompt = "T(1)=1 et T(n)=2T(n/2)+n sur les puissances de deux. Combien vaut T(8) ?", options = listOf("32", "24", "16", "64"), correctOptionIndex = 0, explanation = "T(2)=4, T(4)=12, T(8)=2×12+8=32. Le terme des feuilles compte aussi.", hint = "Commence par la condition initiale."),
            Exercise.MultipleChoice(id = "mit_6_042j_2010_s014_e03", prompt = "Quel ordre a T(n)=2T(n/2)+n dans ce domaine ?", options = listOf("Θ(log n)", "Θ(n²)", "Θ(2^n)", "Θ(n log n)"), correctOptionIndex = 3, explanation = "Il y a log₂n niveaux, chacun de coût n, plus les feuilles de coût linéaire.", hint = "Additionne le travail total par niveau."),
            Exercise.MultipleChoice(id = "mit_6_042j_2010_s014_e04", prompt = "Si S(n)=n-1, que donne S(⌊n/2⌋)+S(⌈n/2⌉)+1 pour n≥2 ?", options = listOf("n+1", "2n-1", "n-1", "n"), correctOptionIndex = 2, explanation = "La somme vaut ⌊n/2⌋-1+⌈n/2⌉-1+1=n-1. Les sous-tailles sont strictement plus petites, ce qui autorise la récurrence forte.", hint = "Utilise l’identité plancher plus plafond égale n.")
        ),
        objective = "Dérouler un arbre récursif et justifier une formule proposée.",
        learningNotes = "Une récurrence relie le coût d'un problème aux coûts de sous-problèmes. Les tours de Hanoï donnent H(n)=2H(n-1)+1 avec H(0)=0 : déplacer les n-1 petits disques, le grand, puis les petits. En développant, on obtient H(n)=2^n-1 et une récurrence permet de vérifier cette formule. Pour T(n)=2T(n/2)+n sur les puissances de deux, chaque niveau de l'arbre demande au total n unités. Il y a log₂n niveaux de division, d'où un ordre n log n. Les conditions initiales déterminent les termes constants. Une autre relation S(n)=S(⌊n/2⌋)+S(⌈n/2⌉)+1, S(1)=0, donne n-1, car les deux tailles s'additionnent à n. Deviner une formule à partir de quelques valeurs doit être suivi d'une preuve.",
        sourceUrls = listOf("https://ocw.mit.edu/courses/6-042j-mathematics-for-computer-science-fall-2010/resources/lecture-14-divide-and-conquer-recurrences/", "https://ocw.mit.edu/courses/6-042j-mathematics-for-computer-science-fall-2010/fa1c71923e2802c8415a16fadb541bb0_Kqf0uO0oV6s.pdf", "https://ocw.mit.edu/courses/6-042j-mathematics-for-computer-science-fall-2010/18b5495f7408055f9679e3afebb108ab_MIT6_042JF10_chap10.pdf"),
        requiresPreviousLesson = true,
