            Exercise.MathChallenge(id = "mit_6_042j_2010_s016_e03", prompt = "Quel est le reste de 7^22 modulo 23 ?", options = listOf("22", "1", "0", "7"), correctOptionIndex = 1, explanation = "23 est premier et ne divise pas 7. Le petit théorème de Fermat donne 7^22≡1 modulo 23.", hint = "Vérifie d’abord les hypothèses du théorème."),
            Exercise.MathChallenge(id = "mit_6_042j_2010_s016_e04", prompt = "Un graphe connexe a sept sommets et neuf arêtes. Combien d’arêtes faut-il retirer pour obtenir un arbre couvrant en ne retirant que des arêtes de cycles ?", options = listOf("3", "2", "4", "6"), correctOptionIndex = 0, explanation = "Un arbre couvrant a 6 arêtes. En retirer 9-6=3 sur des cycles préserve la connexité et supprime les redondances.", hint = "Compare le nombre d’arêtes actuel à celui d’un arbre."),
            Exercise.MultipleChoice(id = "mit_6_042j_2010_s016_e05", prompt = "Un cycle simple de cinq sommets admet-il un circuit eulérien non orienté ?", options = listOf("Non, car son nombre de sommets est impair.", "Non, car un cycle ne peut pas être eulérien.", "Oui, parce que tous ses degrés sont impairs.", "Oui, il est connexe et tous ses degrés valent deux."), correctOptionIndex = 3, explanation = "Un parcours autour du cycle utilise chaque arête une fois et revient au départ. La parité pertinente est celle des degrés.", hint = "Ne confonds pas parité du nombre de sommets et parité des degrés."),
