    private fun lesson017() = Lesson(
        id = "mit_6_042j_2010_s017",
        title = "Résoudre une récurrence linéaire",
        xpReward = 20,
        isLocked = false,
        exercises = listOf(
            Exercise.MathChallenge(id = "mit_6_042j_2010_s017_e01", prompt = "Pour a0=2, a1=5 et an=5an-1-6an-2, combien vaut a4 ?", options = listOf("65", "48", "97", "81"), correctOptionIndex = 2, explanation = "La formule 2^n+3^n donne 16+81=97. On peut aussi calculer 13,35,97 après les deux premiers termes.", hint = "Vérifie les deux conditions initiales avant d’utiliser la formule."),
            Exercise.MultipleChoice(id = "mit_6_042j_2010_s017_e02", prompt = "Quelles sont les racines de r²-7r+12 ?", options = listOf("-3 et -4", "3 et 4", "2 et 6", "1 et 12"), correctOptionIndex = 1, explanation = "Le produit des racines vaut 12 et leur somme 7 ; (r-3)(r-4) convient.", hint = "Cherche deux nombres avec le bon produit et la bonne somme."),
            Exercise.MultipleChoice(id = "mit_6_042j_2010_s017_e03", prompt = "Pour une racine caractéristique double égale à 2, quelle forme générale est nécessaire ?", options = listOf("(A+Bn)2^n", "A2^n+B2^n", "A+B", "A2^(n²)"), correctOptionIndex = 0, explanation = "Le second terme indépendant est n2^n. Deux multiples de 2^n se regrouperaient en un seul coefficient.", hint = "Deux conditions initiales exigent deux paramètres réellement indépendants."),
            Exercise.MathChallenge(id = "mit_6_042j_2010_s017_e04", prompt = "Si bn=2bn-1, b0=3, quelle valeur a b6 ?", options = listOf("64", "96", "729", "192"), correctOptionIndex = 3, explanation = "La suite double six fois : b6=3×2^6=192.", hint = "Le coefficient initial reste un facteur de la puissance.")
        ),
        objective = "Utiliser les racines caractéristiques et les conditions initiales.",
        learningNotes = "Une récurrence linéaire homogène à coefficients constants admet des solutions exponentielles r^n lorsque r satisfait son équation caractéristique. Pour a_n=5a_(n-1)-6a_(n-2), cette équation est r²-5r+6=(r-2)(r-3). La solution générale s'écrit A2^n+B3^n, puis deux conditions initiales déterminent A et B. Si a0=2 et a1=5, les équations A+B=2 et 2A+3B=5 donnent A=B=1. En cas de racine double r, il faut inclure un terme n r^n : deux copies identiques de r^n ne fournissent pas deux paramètres indépendants. La formule obtenue doit satisfaire à la fois la relation et les conditions initiales. Vérifier seulement la relation laisse encore plusieurs suites possibles.",
        sourceUrls = listOf("https://ocw.mit.edu/courses/6-042j-mathematics-for-computer-science-fall-2010/resources/lecture-15-linear-recurrences/", "https://ocw.mit.edu/courses/6-042j-mathematics-for-computer-science-fall-2010/eb8fc3c5ca462d307112e4fcedda39da_TWBB-JlmYUc.pdf", "https://ocw.mit.edu/courses/6-042j-mathematics-for-computer-science-fall-2010/18b5495f7408055f9679e3afebb108ab_MIT6_042JF10_chap10.pdf"),
        requiresPreviousLesson = true,
        sourceSessionNumber = 17,
        sourceTitle = "Lecture 15: Linear Recurrences",
        sessionKind = "lesson"
    )

    private fun lesson018() = Lesson(
        id = "mit_6_042j_2010_s018",
        title = "Compter par correspondances et tiroirs",
        xpReward = 20,
        isLocked = false,
        exercises = listOf(
            Exercise.MathChallenge(id = "mit_6_042j_2010_s018_e01", prompt = "Un code comporte deux lettres choisies parmi quatre, puis un chiffre parmi dix, avec répétition autorisée. Combien de codes existe-t-il ?", options = listOf("24", "160", "80", "40"), correctOptionIndex = 1, explanation = "Les choix sont indépendants au sens du dénombrement : 4×4×10=160.", hint = "Compte les possibilités à chaque position."),
            Exercise.MathChallenge(id = "mit_6_042j_2010_s018_e02", prompt = "Combien de personnes suffisent pour garantir que deux sont nées dans le même mois ?", options = listOf("13", "12", "24", "2"), correctOptionIndex = 0, explanation = "Douze mois peuvent recevoir douze personnes sans collision. La treizième force une répétition par le principe des tiroirs.", hint = "Compare nombre d’objets et nombre de catégories."),
            Exercise.MultipleChoice(id = "mit_6_042j_2010_s018_e03", prompt = "On forme une paire non ordonnée de deux personnes distinctes parmi six. Pourquoi diviser 6×5 par deux ?", options = listOf("Chaque personne est choisie deux fois dans la paire.", "Il y a seulement deux personnes disponibles.", "Le choix initial est impossible.", "Chaque paire est représentée par ses deux ordres possibles."), correctOptionIndex = 3, explanation = "Les listes (A,B) et (B,A) représentent la même paire et chaque paire possède exactement deux représentations.", hint = "Contrôle que la multiplicité est la même pour tous les objets."),
            Exercise.MathChallenge(id = "mit_6_042j_2010_s018_e04", prompt = "Sept objets sont répartis dans trois tiroirs. Quelle taille minimale peut-on garantir pour le tiroir le plus rempli ?", options = listOf("4", "7", "3", "2"), correctOptionIndex = 2, explanation = "Si chaque tiroir contenait au plus deux objets, le total serait au plus six. Il y en a sept, donc l’un en contient au moins trois.", hint = "Raisonne par contradiction sur une capacité maximale.")
        ),
        objective = "Choisir une représentation sans perte ni double comptage.",
        learningNotes = "Compter un ensemble devient plus simple lorsqu'on le met en bijection avec un ensemble déjà compris. La règle du produit décrit des choix successifs dont le nombre d'options est connu à chaque étape. La règle de la somme concerne des cas disjoints. Une application qui associe exactement k représentations à chaque objet permet de diviser le nombre de représentations par k. Le principe des tiroirs affirme que plus d'objets que de catégories forcent au moins une catégorie à recevoir plusieurs objets. Avec treize personnes réparties entre douze mois de naissance, deux partagent donc un mois, sans identifier lesquelles. Ce type de preuve d'existence n'exige pas de construire la paire. Une mauvaise représentation peut oublier des contraintes ou compter certains objets plus souvent que d'autres.",
        sourceUrls = listOf("https://ocw.mit.edu/courses/6-042j-mathematics-for-computer-science-fall-2010/resources/lecture-16-counting-rules-i/", "https://ocw.mit.edu/courses/6-042j-mathematics-for-computer-science-fall-2010/d9cfa23d44c5aa8f81fae627d0bb30dd_pNt5Ll6hGqo.pdf", "https://ocw.mit.edu/courses/6-042j-mathematics-for-computer-science-fall-2010/fd14182dfb1a679eda5cbd38c48c8bb5_MIT6_042JF10_chap11.pdf"),
        requiresPreviousLesson = true,
        sourceSessionNumber = 18,
        sourceTitle = "Lecture 16: Counting Rules I",
        sessionKind = "lesson"
    )

    private fun lesson019() = Lesson(
        id = "mit_6_042j_2010_s019",
        title = "Choisir des sous-ensembles et corriger les recouvrements",
