            Exercise.MathChallenge(id = "mit_6_042j_2010_s019_e01", prompt = "Combien de comités non ordonnés de trois personnes peut-on choisir parmi huit ?", options = listOf("56", "24", "336", "512"), correctOptionIndex = 0, explanation = "C(8,3)=8×7×6/(3×2×1)=56. Les six ordres de chaque comité désignent le même ensemble.", hint = "Le choix ne comporte pas de fonctions distinctes."),
            Exercise.MathChallenge(id = "mit_6_042j_2010_s019_e02", prompt = "Dans un groupe, 18 personnes parlent A, 15 parlent B et 7 parlent les deux. Combien parlent au moins une de ces langues ?", options = listOf("33", "40", "19", "26"), correctOptionIndex = 3, explanation = "18+15 compte deux fois les sept bilingues. En les retranchant une fois, on obtient 26.", hint = "L’expression « au moins une » désigne une union."),
            Exercise.MathChallenge(id = "mit_6_042j_2010_s019_e03", prompt = "Combien d’arrangements distincts des lettres AABBC existe-t-il ?", options = listOf("60", "20", "30", "120"), correctOptionIndex = 2, explanation = "Il y a 5! permutations de positions, mais permuter les deux A ou les deux B ne change pas le mot : 5!/(2!2!)=30.", hint = "Corrige chaque famille de lettres répétées."),
            Exercise.MathChallenge(id = "mit_6_042j_2010_s019_e04", prompt = "Combien de mains de cinq cartes contiennent exactement quatre rois, dans un jeu de 52 cartes ?", options = listOf("624", "48", "13", "52"), correctOptionIndex = 1, explanation = "Les quatre rois sont imposés. La cinquième carte est l’une des 48 autres cartes. Le total 624 concernerait quatre cartes de n’importe quel rang.", hint = "Ne multiplie pas par les rangs quand celui des quatre cartes est déjà fixé.")
        ),
        objective = "Appliquer coefficients binomiaux, inclusion-exclusion et multinomiaux.",
        learningNotes = "Un choix de k objets parmi n sans ordre se compte par C(n,k)=n!/(k!(n-k)!). Les permutations internes des objets choisis ne doivent pas créer de nouveaux choix. Pour une répartition en groupes étiquetés de tailles fixées, un coefficient multinomial divise les permutations par les factorielles de chaque groupe. L'inclusion-exclusion corrige un autre double comptage : |A∪B|=|A|+|B|-|A∩B|, car l'intersection a été comptée deux fois. Pour trois ensembles, on retranche les intersections deux à deux puis on rétablit l'intersection triple. Les mains de cartes illustrent ces distinctions : une main est un ensemble, mais sa description peut choisir d'abord des rangs puis des couleurs. Il faut vérifier qu'une description correspond à une unique main ou corriger sa multiplicité.",
        sourceUrls = listOf("https://ocw.mit.edu/courses/6-042j-mathematics-for-computer-science-fall-2010/resources/lecture-17-counting-rules-ii/", "https://ocw.mit.edu/courses/6-042j-mathematics-for-computer-science-fall-2010/545c0e4f7df07d15c4fbf6d3d0ed77dc_09yIb3VHhMI.pdf", "https://ocw.mit.edu/courses/6-042j-mathematics-for-computer-science-fall-2010/fd14182dfb1a679eda5cbd38c48c8bb5_MIT6_042JF10_chap11.pdf"),
        requiresPreviousLesson = true,
        sourceSessionNumber = 19,
        sourceTitle = "Lecture 17: Counting Rules II",
        sessionKind = "lesson"
    )

