        ),
        objective = "Modéliser les issues et leurs poids avant de compter un événement.",
        learningNotes = "Un modèle probabiliste comprend un ensemble d'issues, des événements et des probabilités totalisant un. Dans un espace fini équiprobable, la probabilité d'un événement est le rapport des issues favorables au nombre total. Sans équiprobabilité, il faut additionner leurs poids. Deux dés distinguables donnent trente-six couples équiprobables, mais leurs onze sommes possibles ne le sont pas. Un arbre aide à décrire les étapes : on multiplie les probabilités conditionnelles le long d'une branche et on additionne celles de branches disjointes. Le problème des trois portes montre que les règles de l'animateur comptent : lorsqu'il sait où se trouve le prix, ouvre toujours une porte perdante et offre toujours de changer, le changement gagne exactement quand le premier choix était faux, soit avec probabilité deux tiers.",
        sourceUrls = listOf("https://ocw.mit.edu/courses/6-042j-mathematics-for-computer-science-fall-2010/resources/lecture-18-probability-introduction/", "https://ocw.mit.edu/courses/6-042j-mathematics-for-computer-science-fall-2010/e38df7d17bc4b9e21ac6c9347279a8d0_SmFwFdESMHI.pdf", "https://ocw.mit.edu/courses/6-042j-mathematics-for-computer-science-fall-2010/67563e626df1b795165a7bf1426cc166_MIT6_042JF10_chap14.pdf"),
        requiresPreviousLesson = true,
        sourceSessionNumber = 20,
        sourceTitle = "Lecture 18: Probability Introduction",
        sessionKind = "lesson"
    )

    private fun lesson021() = Lesson(
        id = "mit_6_042j_2010_s021",
        title = "Conditionner et inverser une information",
        xpReward = 20,
