        exercises = listOf(
            Exercise.MathChallenge(id = "mit_6_042j_2010_s021_e01", prompt = "Parmi 100 objets, 30 sont rouges, 20 sont grands et 12 sont à la fois rouges et grands. Quelle est la probabilité d’être rouge sachant que l’objet est grand ?", options = listOf("3/10", "3/25", "3/5", "2/5"), correctOptionIndex = 2, explanation = "Le nouvel univers contient les 20 grands objets, dont 12 rouges : 12/20=3/5.", hint = "Le dénominateur correspond à l’événement connu."),
            Exercise.MathChallenge(id = "mit_6_042j_2010_s021_e02", prompt = "Une pièce est défectueuse avec probabilité 1/10. Le contrôle signale avec probabilités 9/10 si elle est défectueuse et 1/5 sinon. Quelle est la probabilité totale d’un signal ?", options = listOf("9/10", "27/100", "9/100", "1/5"), correctOptionIndex = 1, explanation = "P(signal)=1/10×9/10+9/10×1/5=9/100+18/100=27/100.", hint = "Sépare les deux catégories disjointes de pièces."),
            Exercise.MathChallenge(id = "mit_6_042j_2010_s021_e03", prompt = "Dans le modèle précédent, quelle est la probabilité de défaut sachant qu’un signal est apparu ?", options = listOf("1/3", "9/10", "1/10", "2/3"), correctOptionIndex = 0, explanation = "Le numérateur vaut 9/100 et le dénominateur 27/100 ; leur quotient vaut 1/3.", hint = "Renormalise parmi tous les signaux."),
            Exercise.MultipleChoice(id = "mit_6_042j_2010_s021_e04", prompt = "P(A|B) est définie par un quotient. Quelle hypothèse est nécessaire ?", options = listOf("P(A)=P(B)", "A et B disjoints", "P(A)=1", "P(B)>0"), correctOptionIndex = 3, explanation = "On divise par P(B). La définition élémentaire n’attribue pas de quotient lorsque cet événement a une probabilité nulle.", hint = "Regarde le dénominateur de la définition.")
        ),
        objective = "Appliquer probabilités totales et formule de Bayes.",
        learningNotes = "Conditionner par B restreint l'univers à cet événement puis renormalise ses poids : P(A|B)=P(A∩B)/P(B), si P(B)>0. Il faut distinguer cette probabilité de P(B|A). Supposons qu'une machine produise 10 % de pièces défectueuses, qu'un contrôle signale 90 % des défauts et fasse aussi un signal sur 20 % des pièces saines. Sur mille pièces représentatives, on attend quatre-vingt-dix vrais signaux et cent quatre-vingts faux signaux. Parmi les deux cent soixante-dix signaux, la proportion de défauts est donc un tiers. La formule de Bayes organise ce calcul avec la fréquence préalable et les deux comportements du contrôle. Une information nouvelle peut ainsi changer fortement la probabilité sans transformer le test en certitude.",
