    )

    private fun lesson022() = Lesson(
        id = "mit_6_042j_2010_s022",
        title = "Vérifier l’indépendance au bon niveau",
        xpReward = 20,
        isLocked = false,
        exercises = listOf(
            Exercise.MathChallenge(id = "mit_6_042j_2010_s022_e01", prompt = "A et B sont indépendants, P(A)=2/5 et P(B)=3/4. Quelle est P(A∩B) ?", options = listOf("1/2", "3/10", "23/20", "1/5"), correctOptionIndex = 1, explanation = "L’indépendance autorise le produit : 2/5×3/4=6/20=3/10.", hint = "N’utilise pas une addition pour une intersection indépendante."),
            Exercise.MultipleChoice(id = "mit_6_042j_2010_s022_e02", prompt = "A et B sont disjoints avec chacun une probabilité strictement positive. Peuvent-ils être indépendants ?", options = listOf("Non : leur intersection a probabilité zéro mais leur produit est positif.", "Oui, car disjoint signifie indépendant.", "Oui, seulement s’ils ont la même probabilité.", "Oui, pour n’importe quelles probabilités positives."), correctOptionIndex = 0, explanation = "L’égalité d’indépendance ne peut pas tenir entre zéro et un produit positif.", hint = "Compare les deux côtés de P(A∩B)=P(A)P(B)."),
            Exercise.MathChallenge(id = "mit_6_042j_2010_s022_e03", prompt = "Deux bits uniformes indépendants X,Y définissent A={X=0}, B={Y=0}, C={X=Y}. Quelle probabilité a A∩B∩C ?", options = listOf("1/8", "1/2", "0", "1/4"), correctOptionIndex = 3, explanation = "Seule l’issue (0,0) parmi les quatre équiprobables convient. Le produit des trois probabilités marginales vaut 1/8, donc l’indépendance mutuelle échoue.", hint = "Énumère les quatre couples binaires."),
            Exercise.MathChallenge(id = "mit_6_042j_2010_s022_e04", prompt = "Trois anniversaires sont uniformes et indépendants sur cinq jours. Quelle probabilité a au moins une collision ?", options = listOf("3/5", "1/5", "13/25", "12/25"), correctOptionIndex = 2, explanation = "L’absence de collision a probabilité 5×4×3/125=12/25. Le complément vaut 13/25.", hint = "Il est plus simple de compter trois dates distinctes.")
        ),
        objective = "Distinguer indépendance mutuelle, deux à deux et incompatibilité.",
        learningNotes = "Deux événements A et B sont indépendants lorsque P(A∩B)=P(A)P(B). Ils sont incompatibles si leur intersection est vide. Deux événements incompatibles de probabilités positives ne sont donc pas indépendants. Pour plusieurs événements, vérifier toutes les paires ne garantit pas l'indépendance mutuelle. Prenons deux bits uniformes indépendants X et Y : les événements X=0, Y=0 et X=Y sont indépendants deux à deux, mais l'intersection triple a probabilité un quart plutôt qu'un huitième. Les produits de probabilités dans un modèle de collision ou de succès répétés demandent donc les hypothèses appropriées. Pour trois anniversaires uniformes indépendants sur cinq jours possibles, la probabilité d'absence de collision est 5×4×3/5³. Le complément donne la probabilité d'au moins une répétition.",
        sourceUrls = listOf("https://ocw.mit.edu/courses/6-042j-mathematics-for-computer-science-fall-2010/resources/lecture-20-independence/", "https://ocw.mit.edu/courses/6-042j-mathematics-for-computer-science-fall-2010/6388bd9f7ac0cad66c505d5f76c4ffef_l1BCv3qqW4A.pdf", "https://ocw.mit.edu/courses/6-042j-mathematics-for-computer-science-fall-2010/9907ae0740731964bce45d8fc06989d2_MIT6_042JF10_chap16.pdf"),
        requiresPreviousLesson = true,
        sourceSessionNumber = 22,
        sourceTitle = "Lecture 20: Independence",
        sessionKind = "lesson"
    )

    private fun lesson023() = Lesson(
        id = "mit_6_042j_2010_s023",
        title = "Décrire une variable aléatoire par sa loi",
        xpReward = 20,
        isLocked = false,
        exercises = listOf(
            Exercise.MathChallenge(id = "mit_6_042j_2010_s023_e01", prompt = "X compte les faces sur deux lancers indépendants équilibrés. Combien vaut P(X=1) ?", options = listOf("1/2", "1/4", "3/4", "1"), correctOptionIndex = 0, explanation = "Les issues FP et PF conviennent parmi FF,FP,PF,PP, toutes équiprobables.", hint = "Regroupe les issues par nombre de faces."),
            Exercise.MathChallenge(id = "mit_6_042j_2010_s023_e02", prompt = "X suit une loi binomiale de paramètres 4 et 1/3. Quelle est P(X=2) ?", options = listOf("4/27", "2/9", "16/81", "8/27"), correctOptionIndex = 3, explanation = "C(4,2)(1/3)²(2/3)²=6×4/81=8/27.", hint = "Choisis d’abord les deux positions des succès."),
            Exercise.MathChallenge(id = "mit_6_042j_2010_s023_e03", prompt = "X vaut 0,1,2 avec probabilités 1/4,1/2,1/4. Combien vaut F(1) ?", options = listOf("1/4", "1", "3/4", "1/2"), correctOptionIndex = 2, explanation = "F(1)=P(X≤1) inclut les masses de 0 et de 1, soit 1/4+1/2=3/4.", hint = "Le signe est inférieur ou égal, pas strictement inférieur."),
            Exercise.MultipleChoice(id = "mit_6_042j_2010_s023_e04", prompt = "Quelle situation justifie directement une loi binomiale ?", options = listOf("Des probabilités de succès différentes à chaque essai sans autre analyse.", "Un nombre fixé d’essais indépendants ayant tous la même probabilité de succès.", "Des essais arbitrairement dépendants.", "Un nombre de succès toujours fixé à l’avance."), correctOptionIndex = 1, explanation = "Le nombre d’essais, leur indépendance et la constance du paramètre p fondent la formule binomiale.", hint = "Vérifie séparément les trois hypothèses.")
        ),
        objective = "Passer d’issues élémentaires à une distribution et une fonction de répartition.",
        learningNotes = "Une variable aléatoire est une fonction qui associe une valeur à chaque issue. Plusieurs issues peuvent produire la même valeur. Sa loi regroupe leurs probabilités. Pour le nombre de faces sur deux lancers indépendants équilibrés, les valeurs 0,1,2 ont respectivement les probabilités un quart, une moitié et un quart. La fonction de répartition F(t)=P(X≤t) est croissante et prend en compte toutes les valeurs jusqu'au seuil, y compris une masse exactement au seuil. La loi binomiale compte les succès dans n essais indépendants de même probabilité p : P(X=k)=C(n,k)p^k(1-p)^(n-k). Le coefficient choisit les positions des succès. Le produit donne le poids de chacune de ces configurations. Des essais dépendants n'autorisent pas automatiquement cette loi.",
        sourceUrls = listOf("https://ocw.mit.edu/courses/6-042j-mathematics-for-computer-science-fall-2010/resources/lecture-21-random-variables/", "https://ocw.mit.edu/courses/6-042j-mathematics-for-computer-science-fall-2010/26637c51d9ed01c61aa160f5f4a20e26_MOfhhFaQdjw.pdf", "https://ocw.mit.edu/courses/6-042j-mathematics-for-computer-science-fall-2010/6942723a3a99c1e7cfe0c3210b6f13ca_MIT6_042JF10_chap17.pdf"),
        requiresPreviousLesson = true,
        sourceSessionNumber = 23,
        sourceTitle = "Lecture 21: Random Variables",
        sessionKind = "lesson"
    )

    private fun lesson024() = Lesson(
        id = "mit_6_042j_2010_s024",
        title = "Calculer une espérance par indicatrices",
        xpReward = 20,
        isLocked = false,
        exercises = listOf(
            Exercise.MathChallenge(id = "mit_6_042j_2010_s024_e01", prompt = "Un dé équilibré à six faces vaut D. Quelle est E[D] ?", options = listOf("3", "7", "21", "7/2"), correctOptionIndex = 3, explanation = "La moyenne pondérée est (1+2+3+4+5+6)/6=21/6=7/2. Elle ne correspond pas à une face.", hint = "Les six faces ont le même poids."),
            Exercise.MathChallenge(id = "mit_6_042j_2010_s024_e02", prompt = "Une permutation uniforme de six étiquettes est choisie. Quel est le nombre moyen d’étiquettes à leur place ?", options = listOf("3", "6", "1", "0"), correctOptionIndex = 2, explanation = "Chaque position a probabilité 1/6 d’être correcte. La somme de six indicatrices a espérance 6×1/6=1.", hint = "La linéarité s’applique même si les positions ne sont pas indépendantes."),
            Exercise.MathChallenge(id = "mit_6_042j_2010_s024_e03", prompt = "X et Y peuvent être dépendantes, E[X]=4 et E[Y]=7. Quelle est E[2X+Y] ?", options = listOf("Impossible à déterminer malgré ces espérances finies.", "15", "11", "28"), correctOptionIndex = 1, explanation = "La linéarité donne 2×4+7=15 sans hypothèse d’indépendance.", hint = "Sépare somme et produit de variables aléatoires."),
            Exercise.MathChallenge(id = "mit_6_042j_2010_s024_e04", prompt = "X est entier non négatif et vaut au plus 3. Si P(X≥1)=3/4, P(X≥2)=1/2 et P(X≥3)=1/4, quelle est E[X] ?", options = listOf("3/2", "1", "3/4", "2"), correctOptionIndex = 0, explanation = "La formule des queues donne 3/4+1/2+1/4=3/2. Les queues suivantes sont nulles.", hint = "Additionne les probabilités de dépasser chaque niveau entier positif.")
        ),
        objective = "Utiliser la linéarité sans supposer une indépendance inutile.",
        learningNotes = "L'espérance est une moyenne pondérée : E[X]=ΣxP(X=x) lorsque la somme est bien définie. Elle ne doit pas être une valeur que X peut effectivement prendre. La linéarité E[X+Y]=E[X]+E[Y] ne demande pas l'indépendance. Une variable indicatrice I_A vaut un lorsque A se produit et zéro sinon. Son espérance est P(A). Pour une permutation uniforme de n étiquettes, le nombre de positions correctement occupées est une somme de n indicatrices, chacune d'espérance 1/n. Son espérance vaut donc un, même si ces indicatrices sont dépendantes. Une autre identité pour X entier non négatif est E[X]=Σ pour k≥1 de P(X≥k) : chaque issue de valeur x est comptée exactement x fois dans les queues de distribution.",
        sourceUrls = listOf("https://ocw.mit.edu/courses/6-042j-mathematics-for-computer-science-fall-2010/resources/lecture-22-expectation-i/", "https://ocw.mit.edu/courses/6-042j-mathematics-for-computer-science-fall-2010/8d9320ea601c41975fb1e2cdc0c99c40_gGlMSe7uEkA.pdf", "https://ocw.mit.edu/courses/6-042j-mathematics-for-computer-science-fall-2010/b61628dbe4b2e1d264f12c8ada491766_MIT6_042JF10_chap18.pdf"),
        requiresPreviousLesson = true,
