        sourceTitle = "Lecture 22: Expectation I",
        sessionKind = "lesson"
    )

    private fun lesson025() = Lesson(
        id = "mit_6_042j_2010_s025",
        title = "Mesurer la dispersion et compter des événements",
        xpReward = 20,
        isLocked = false,
        exercises = listOf(
            Exercise.MathChallenge(id = "mit_6_042j_2010_s025_e01", prompt = "X est une indicatrice avec P(X=1)=1/4. Quelle est sa variance ?", options = listOf("1/16", "3/4", "3/16", "1/4"), correctOptionIndex = 2, explanation = "Var(X)=p(1-p)=1/4×3/4=3/16.", hint = "Utilise X²=X."),
            Exercise.MathChallenge(id = "mit_6_042j_2010_s025_e02", prompt = "Quatre indicatrices indépendantes ont chacune la variance 3/16. Quelle est la variance de leur somme ?", options = listOf("9/16", "3/4", "3/16", "3"), correctOptionIndex = 1, explanation = "L’indépendance annule les covariances ; la somme vaut 4×3/16=3/4.", hint = "Il s’agit d’une variance, pas d’un écart type."),
            Exercise.MathChallenge(id = "mit_6_042j_2010_s025_e03", prompt = "X vaut -1 ou 3 avec probabilités 1/2 chacune. Quelle est sa variance ?", options = listOf("4", "1", "2", "5"), correctOptionIndex = 0, explanation = "E[X]=1 et E[X²]=(1+9)/2=5. Donc Var(X)=5-1²=4.", hint = "Calcule d’abord les deux premiers moments."),
            Exercise.MathChallenge(id = "mit_6_042j_2010_s025_e04", prompt = "Cent événements sont exactement le même événement A, de probabilité 1/100. Leur compteur a espérance 1. Quelle probabilité a au moins un événement ?", options = listOf("1", "1/2", "0", "1/100"), correctOptionIndex = 3, explanation = "Tous arrivent ensemble ou pas du tout. L’union est simplement A, de probabilité 1/100, malgré un nombre moyen d’occurrences égal à 1.", hint = "Une répétition dépendante ne crée pas cent chances indépendantes.")
        ),
        objective = "Calculer une variance et préciser les usages de l’indépendance.",
        learningNotes = "L'espérance ne décrit pas à elle seule la dispersion. La variance est E[(X-E[X])²], également égale à E[X²]-E[X]² lorsque ces moments existent. Pour une indicatrice de probabilité p, X²=X et la variance vaut p(1-p). La variance d'une somme additionne celles des termes indépendants. Sans indépendance, des covariances peuvent intervenir. Le nombre d'événements survenus s'écrit comme une somme d'indicatrices. Sa moyenne fournit toujours un majorant de la probabilité qu'il y ait au moins un événement, puisque le compteur vaut alors au moins un. Une grande moyenne, en revanche, ne garantit pas à elle seule une forte probabilité d'occurrence : des événements très dépendants peuvent se produire tous ensemble très rarement. Les hypothèses déterminent donc le sens des conclusions possibles.",
        sourceUrls = listOf("https://ocw.mit.edu/courses/6-042j-mathematics-for-computer-science-fall-2010/resources/lecture-23-expectation-ii/", "https://ocw.mit.edu/courses/6-042j-mathematics-for-computer-science-fall-2010/dc4f198af215cde514be1c46c806d063_oI9fMUqgfxY.pdf", "https://ocw.mit.edu/courses/6-042j-mathematics-for-computer-science-fall-2010/b61628dbe4b2e1d264f12c8ada491766_MIT6_042JF10_chap18.pdf", "https://ocw.mit.edu/courses/6-042j-mathematics-for-computer-science-fall-2010/6c942e0720244be28959e968aae62e16_MIT6_042JF10_chap19.pdf"),
        requiresPreviousLesson = true,
        sourceSessionNumber = 25,
        sourceTitle = "Lecture 23: Expectation II",
        sessionKind = "lesson"
    )

    private fun lesson026() = Lesson(
        id = "mit_6_042j_2010_s026",
        title = "Borner les grands écarts",
        xpReward = 20,
        isLocked = false,
        exercises = listOf(
            Exercise.MathChallenge(id = "mit_6_042j_2010_s026_e01", prompt = "X≥0 et E[X]=8. Quel majorant Markov donne-t-il pour P(X≥40) ?", options = listOf("0", "1/5", "1/8", "5"), correctOptionIndex = 1, explanation = "Markov donne E[X]/40=8/40=1/5. C’est une borne supérieure, pas nécessairement la probabilité réelle.", hint = "Identifie le seuil positif."),
            Exercise.MathChallenge(id = "mit_6_042j_2010_s026_e02", prompt = "Var(X)=9. Quel majorant Chebyshev donne-t-il pour P(|X-E[X]|≥6) ?", options = listOf("1/4", "1/2", "3/2", "1/36"), correctOptionIndex = 0, explanation = "La borne est 9/6²=9/36=1/4.", hint = "Le seuil est élevé au carré."),
            Exercise.MultipleChoice(id = "mit_6_042j_2010_s026_e03", prompt = "Quelle hypothèse est indispensable à la version de Chernoff enseignée pour une somme de variables dans [0,1] ?", options = listOf("Une espérance nulle de tous les termes.", "Une valeur toujours entière de chaque terme.", "Une égalité de tous les termes entre eux.", "L’indépendance mutuelle des termes."), correctOptionIndex = 3, explanation = "La factorisation des espérances exponentielles utilise l’indépendance mutuelle. Des termes identiques et dépendants ne conviennent pas.", hint = "La preuve combine une transformation exponentielle et un produit."),
            Exercise.MultipleChoice(id = "mit_6_042j_2010_s026_e04", prompt = "Pour c=2, quelle expression vaut c ln c-c+1 ?", options = listOf("2 ln 2+1", "1-2 ln 2", "2 ln 2-1", "ln 2"), correctOptionIndex = 2, explanation = "La substitution donne 2 ln 2-2+1=2 ln 2-1, qui est positif et produit un exposant négatif dans la borne.", hint = "Conserve tous les termes et leurs signes.")
        ),
        objective = "Choisir entre Markov, Chebyshev et Chernoff selon les hypothèses.",
        learningNotes = "L'inégalité de Markov dit que P(X≥a)≤E[X]/a pour X non négative et a>0. Sa preuve observe que les seules issues où X≥a contribuent déjà au moins aP(X≥a) à l'espérance. Appliquer Markov à (X-E[X])² donne Chebyshev : P(|X-E[X]|≥t)≤Var(X)/t². Cette borne demande une variance finie, mais pas l'indépendance d'une décomposition particulière. Pour une somme de variables mutuellement indépendantes dans [0,1], Chernoff donne des queues exponentielles plus fortes. Avec moyenne μ et c≥1, la borne étudiée est exp(-μ(c ln c-c+1)). Une borne peut dépasser un et devenir peu informative. On conserve alors la borne universelle un. Aucun de ces résultats ne fournit automatiquement une probabilité exacte.",
        sourceUrls = listOf("https://ocw.mit.edu/courses/6-042j-mathematics-for-computer-science-fall-2010/resources/lecture-24-large-deviations/", "https://ocw.mit.edu/courses/6-042j-mathematics-for-computer-science-fall-2010/9f082671fda66fa7b8639a4922bd48fd_q4mwO2qS2z4.pdf", "https://ocw.mit.edu/courses/6-042j-mathematics-for-computer-science-fall-2010/6c942e0720244be28959e968aae62e16_MIT6_042JF10_chap19.pdf"),
        requiresPreviousLesson = true,
        sourceSessionNumber = 26,
        sourceTitle = "Lecture 24: Large Deviations",
        sessionKind = "lesson"
    )

