            Exercise.MathChallenge(id = "mit_6_042j_2010_s027_e01", prompt = "Une marche équilibrée commence à 2 entre les frontières absorbantes 0 et 5. Quelle est la probabilité d’atteindre 5 avant 0 ?", options = listOf("2/5", "1/2", "3/5", "1/5"), correctOptionIndex = 0, explanation = "La solution h_i=i/N donne 2/5 et respecte les deux valeurs aux frontières.", hint = "Utilise le point de départ relatif à la longueur de l’intervalle."),
            Exercise.MathChallenge(id = "mit_6_042j_2010_s027_e02", prompt = "Dans la marche équilibrée précédente, quelle durée moyenne d’absorption donne i(N-i) ?", options = listOf("3", "5", "10", "6"), correctOptionIndex = 3, explanation = "La formule donne 2×(5-2)=6 pas en moyenne. Il ne s’agit pas d’un nombre de pas imposé à chaque trajectoire.", hint = "Substitue la position de départ et la frontière supérieure."),
            Exercise.MathChallenge(id = "mit_6_042j_2010_s027_e03", prompt = "Une marche effectue quatre pas indépendants valant +1 ou -1 avec probabilités égales. Quelle est la probabilité de revenir à zéro ?", options = listOf("1/2", "1/8", "3/8", "1/4"), correctOptionIndex = 2, explanation = "Il faut deux pas +1 et deux pas -1, soit C(4,2)=6 trajectoires sur 16.", hint = "Le retour impose un équilibre entre les deux directions."),
            Exercise.MultipleChoice(id = "mit_6_042j_2010_s027_e04", prompt = "Pourquoi la récurrence de durée contient-elle un terme +1 ?", options = listOf("Le point de départ est toujours 1.", "Le premier pas consomme une unité de temps avant la durée restante.", "La probabilité totale doit dépasser un.", "Il y a toujours un pas après absorption."), correctOptionIndex = 1, explanation = "La décomposition est durée totale = un premier pas + durée depuis la nouvelle position. Aux frontières, la durée vaut zéro.", hint = "Distingue récurrence de probabilité et récurrence de durée.")
        ),
        objective = "Écrire une récurrence d’atteinte et distinguer équilibre et biais.",
        learningNotes = "Une marche aléatoire déplace une position par étapes probabilistes. Pour une marche équilibrée sur les entiers entre 0 et N, absorbée aux frontières, notons h_i la probabilité d'atteindre N avant 0 depuis i. Conditionner sur le premier pas donne h_i=(h_(i-1)+h_(i+1))/2 avec h0=0 et hN=1. La solution h_i=i/N satisfait cette relation et les frontières. Pour N=5 et i=2, elle vaut deux cinquièmes. La durée moyenne d'absorption vaut i(N-i), obtenue avec une récurrence comportant une unité de temps supplémentaire. Un biais modifie les coefficients et la solution : la proximité de la probabilité d'un pas avec un demi ne justifie pas de réutiliser une formule équilibrée. Il faut annoncer règles de déplacement et conditions aux bords.",
